import { describe, it, expect } from 'vitest';
import { existsSync, readFileSync } from 'node:fs';
import sharp from 'sharp';
import { normalizeImage, estimateAlignment, alignEditedCrop, extractOnePassComponents } from '../src/lib/server/imageOps';
import type { BBox } from '../src/lib/engine/types';

/**
 * Offline calibration for one-pass extraction — NO paid calls.
 *
 * Fixture: test.jpeg, the beach photo generated by the game itself (Muse Image,
 * VF_THEME_GENERATION). The previous fixture paired it with a saved Muse edit of
 * an old website flower photo — third-party, since removed — so the pair no longer
 * matched (0 of 3 components, 2026-10-31). This version SYNTHESIZES the edited
 * image locally from test.jpeg: three strong solid edits (the analogues of the
 * original three — an added object, a recolored patch, a dark object) plus a
 * simulated Muse return: 3 px drift, slight softening and a JPEG re-encode.
 * Alignment must undo the drift and extraction must find EXACTLY the 3 edits,
 * separating them from the global re-render noise — the engine thresholds in
 * ONE_PASS_THRESHOLDS were calibrated to do precisely this on real returns.
 */
const available = existsSync('test.jpeg');

describe.skipIf(!available)('one-pass extraction calibration (offline, synthesized edits)', () => {
  it('separates exactly the 3 synthesized edits from re-render noise', async () => {
    const original = await normalizeImage(`data:image/jpeg;base64,${readFileSync('test.jpeg').toString('base64')}`, 1024);
    const { width: W, height: H } = original;

    // Paint the 3 edits on the normalized original (raw RGB).
    const { data } = await sharp(Buffer.from(original.dataUrl.split(',')[1], 'base64')).removeAlpha().raw().toBuffer({ resolveWithObject: true });
    const px = Buffer.from(data);
    const paint = (x: number, y: number, r: number, g: number, b: number) => { const o = (y * W + x) * 3; px[o] = r; px[o + 1] = g; px[o + 2] = b; };
    // 1) Recolored patch (strong solid) — sky-side analogue of the vanished bud.
    const rect: BBox = { x: Math.round(W * 0.24) - 60, y: Math.round(H * 0.26) - 40, width: 120, height: 80 };
    for (let y = rect.y; y < rect.y + rect.height; y++) for (let x = rect.x; x < rect.x + rect.width; x++) paint(x, y, 20, 190, 60);
    // 2) Added object (ladybug analogue): saturated red disc on the empty sand at
    // the bottom centre (on the striped towel its blob bleeds along the stripes —
    // measured while recalibrating; smooth sand is what the analogue needs).
    const disc = (cx: number, cy: number, rad: number, r: number, g: number, b: number): BBox => {
      for (let y = cy - rad; y <= cy + rad; y++) for (let x = cx - rad; x <= cx + rad; x++) if ((x - cx) ** 2 + (y - cy) ** 2 <= rad * rad) paint(x, y, r, g, b);
      return { x: cx - rad, y: cy - rad, width: rad * 2, height: rad * 2 };
    };
    const redDisc = disc(Math.round(W * 0.36), Math.round(H * 0.90), 24, 225, 30, 30);
    // 3) Dark object (droplet analogue): near-black disc mid-frame.
    const darkDisc = disc(Math.round(W * 0.45), Math.round(H * 0.40), 20, 15, 15, 25);

    // Simulate the Muse return: 3 px drift, slight softening, re-encode noise. The
    // drift is applied PIXEL-WISE here (not via sharp extend/extract — sharp applies
    // its operations in its own order, so a chained shift is not the shift asked
    // for: the estimate came back (1,1) for a nominal (3,2) while recalibrating).
    const shifted = Buffer.alloc(px.length);
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
      const sx = Math.max(0, x - 3), sy = Math.max(0, y - 2), d = (y * W + x) * 3, s = (sy * W + sx) * 3;
      shifted[d] = px[s]; shifted[d + 1] = px[s + 1]; shifted[d + 2] = px[s + 2];
    }
    const editedBuf = await sharp(shifted, { raw: { width: W, height: H, channels: 3 } })
      .modulate({ brightness: 1.03 })
      .blur(0.5)
      .jpeg({ quality: 88 })
      .toBuffer();
    const edited = `data:image/jpeg;base64,${editedBuf.toString('base64')}`;

    const est = await estimateAlignment(original.dataUrl, edited);
    console.log(`alignment: shift (${est.shiftX}, ${est.shiftY}) scale ${est.scale} residual ${est.error.toFixed(1)}`);
    const aligned = await alignEditedCrop(original.dataUrl, edited, est);
    const { components, discarded } = await extractOnePassComponents(original.dataUrl, aligned);
    for (const d of discarded) console.log(`discarded: ${d.area}px amp ${d.meanAmp.toFixed(1)} bbox (${d.bbox.x},${d.bbox.y}) ${d.bbox.width}x${d.bbox.height} — ${d.reason}`);
    for (const c of components) console.log(`component: ${c.area}px amp ${c.meanAmp.toFixed(1)} score ${Math.round(c.score)} bbox (${c.bbox.x},${c.bbox.y}) ${c.bbox.width}x${c.bbox.height}`);

    expect(components).toHaveLength(3);
    // Each edit is found with its measured bbox inside the painted box (±20 px of
    // blur/dilation slack) — the same loose-box style as the original calibration.
    const near = (b: BBox, pad = 20) => components.some(c =>
      c.bbox.x >= b.x - pad && c.bbox.y >= b.y - pad &&
      c.bbox.x + c.bbox.width <= b.x + b.width + pad && c.bbox.y + c.bbox.height <= b.y + b.height + pad);
    expect(near(rect), 'recolored patch').toBe(true);
    expect(near(redDisc), 'added red disc').toBe(true);
    expect(near(darkDisc), 'added dark disc').toBe(true);
  }, 60_000);
});
